// Growthic One — Edge Function: birthday-reminders
// Runs daily (pg_cron). Emails ONE reminder per birthday, 7 days ahead:
// To = the birthday person, BCC = every other active employee. Sent once per
// person per year (birthday_reminder_log). Feb 29 birthdays count as Feb 28 in
// non-leap years.
//
// Required env vars:
//   RESEND_API_KEY, SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
//   BIRTHDAY_CRON_SECRET — must match the x-cron-secret header on every call
//
// Test mode (no log, no team email): POST { "test_to": "you@example.com", "test_name": "Priya", "test_date": "2026-11-20" }

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const DAYS_AHEAD    = 7
const FROM_ADDRESS  = 'Growthic One <noreply@thegrowthic.com>'
const APP_BASE_URL  = 'https://one.thegrowthic.com'
const LOGO_URL      = 'https://one.thegrowthic.com/assets/img/logo.jpg'
const JSON_HEADERS  = { 'Content-Type': 'application/json' }
// Public link to the hero image (served by this function, see the GET route below).
// Bump ?v= when the image changes so mail apps fetch the new one.
const HERO_URL      = 'https://sagqqcctagolalfrezwg.supabase.co/functions/v1/birthday-reminders/hero.jpg?v=2'

const MESSAGES = [
  `{name}'s birthday is on {date}. That gives us a week to pretend we didn't forget. Start warming up your best wishes.`,
  `One week to go until {name} levels up on {date}. No patch notes, just cake. Block your calendar for wishes.`,
  `Breaking news: {name} gets a year older on {date}, and allegedly wiser too.`,
  `Our Birthday Desk reports that {name} turns a year older on {date}. Please keep wishes within budget and puns above average.`,
  `Consider this your one-week notice: {name}'s birthday lands on {date}. Our content calendar says "celebrate".`,
  `{name}'s birthday is {date}. Unlike our campaign deadlines, this one cannot be extended.`,
  `A little birdie (our HR system) says {name}'s birthday is on {date}. Cake logistics are loading.`,
  `In a week, {name} adds another year of experience. You have until {date} to come up with something better than "HBD".`,
  `{name}'s birthday is on {date}. A group-chat wish counts, but a personal message counts more.`,
  `Seven sleeps until {name}'s birthday on {date}. Stock up on wishes, compliments and an unreasonable amount of cake.`,
]

function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

// IST has no DST, so a fixed +05:30 offset is exact.
function todayIST(): Date {
  const now = new Date(Date.now() + 5.5 * 3600 * 1000)
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
}

function isLeapYear(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0
}

function formatDate(d: Date): string {
  return d.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'UTC' })
}

function buildHtml(line: string, name: string, date: string, days: number): string {
  return `<!doctype html>
<html>
<body style="margin:0;padding:0;background:#EEF3FA;font-family:Arial,Helvetica,sans-serif;color:#111827;">
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;">${escapeHtml(name)}'s birthday is on ${escapeHtml(date)}. Start warming up your wishes.</div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF3FA;">
    <tr><td align="center" style="padding:24px 12px;">
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;">

        <!-- Hero (attached inline, see HERO_B64) -->
        <tr><td style="font-size:0;line-height:0;background:#1A72C7;">
          <img src="${HERO_URL}" alt="Growthic One: heads up, team! We have a birthday coming up" width="600" style="display:block;width:100%;max-width:600px;height:auto;border:0;">
        </td></tr>

        <!-- Greeting + witty line -->
        <tr><td style="padding:28px 32px 20px;font-size:16px;line-height:1.75;color:#111827;background:#ffffff;">
          <p style="margin:0 0 16px;">Hi team,</p>
          <p style="margin:0;">${line}</p>
        </td></tr>
        <!-- Emoji row -->
        <tr><td align="center" style="padding:6px 24px 30px;background:#ffffff;font-size:30px;line-height:1.2;letter-spacing:12px;">
          &#127874;&#127880;&#127873;&#129395;&#127881;
        </td></tr>

        <!-- Footer: one slim line -->
        <tr><td align="center" style="padding:11px 16px;background:#0F4799;font-size:11px;line-height:1.4;color:#BFD4F2;">
          Growthic One &nbsp;&middot;&nbsp; Automated reminder, please don't reply
        </td></tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`
}

async function sendMail(apiKey: string, payload: Record<string, unknown>) {
  const res = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${apiKey}`, ...JSON_HEADERS },
    body: JSON.stringify(payload),
  })
  const data = await res.json().catch(() => ({}))
  return { ok: res.ok, data }
}

function buildEmail(name: string, birthday: Date) {
  const date = formatDate(birthday)
  const days = Math.max(1, Math.round((birthday.getTime() - todayIST().getTime()) / 86400000))
  const line = MESSAGES[Math.floor(Math.random() * MESSAGES.length)]
    .replaceAll('{name}', `<strong>${escapeHtml(name)}</strong>`).replaceAll('{date}', `<strong>${escapeHtml(date)}</strong>`)
  return {
    subject: `${name}'s birthday is a week away (${date})`,
    html: buildHtml(line, name, date, days),
    headers: {
      'Reply-To': 'noreply@thegrowthic.com',
      'Auto-Submitted': 'auto-generated',
    },
  }
}

Deno.serve(async (req: Request) => {
  // Public image route used by the email's <img>. Serves the hero JPEG, nothing else.
  if (req.method === 'GET' && new URL(req.url).pathname.endsWith('/hero.jpg')) {
    const bytes = Uint8Array.from(atob(HERO_B64), (c) => c.charCodeAt(0))
    return new Response(bytes, {
      headers: { 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=86400' },
    })
  }

  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405 })

  const expected = Deno.env.get('BIRTHDAY_CRON_SECRET')
  if (!expected || req.headers.get('x-cron-secret') !== expected) {
    return new Response(JSON.stringify({ error: 'unauthorized' }), { status: 401, headers: JSON_HEADERS })
  }

  const RESEND_API_KEY = Deno.env.get('RESEND_API_KEY')
  if (!RESEND_API_KEY) {
    return new Response(JSON.stringify({ error: 'RESEND_API_KEY not configured' }), { status: 500, headers: JSON_HEADERS })
  }

  const body = await req.json().catch(() => ({}))

  // Test mode: one sample email to one address only. Nothing is logged and no
  // employee data is read.
  if (body.test_to) {
    const bday = body.test_date ? new Date(`${body.test_date}T00:00:00Z`) : new Date(todayIST().getTime() + DAYS_AHEAD * 86400000)
    const mail = buildEmail(body.test_name || 'Test Person', bday)
    const sent = await sendMail(RESEND_API_KEY, { from: FROM_ADDRESS, to: [body.test_to], ...mail })
    return new Response(JSON.stringify({ test: true, sent: sent.ok, result: sent.data }), { headers: JSON_HEADERS })
  }

  try {
    const supabase = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)

    const target = new Date(todayIST().getTime() + DAYS_AHEAD * 86400000)
    const tMonth = target.getUTCMonth() + 1
    const tDay   = target.getUTCDate()
    const tYear  = target.getUTCFullYear()
    // Feb 29 people are celebrated on Feb 28 in non-leap years.
    const wantFeb29Too = tMonth === 2 && tDay === 28 && !isLeapYear(tYear)

    const { data: employees, error } = await supabase
      .from('employees')
      .select('id, name, email, date_of_birth')
      .eq('status', 'active')
    if (error) throw error

    const withEmail = (employees || []).filter(e => e.email)
    const birthdayPeople = withEmail.filter(e => {
      if (!e.date_of_birth) return false
      const [, m, d] = String(e.date_of_birth).split('-').map(Number)
      return (m === tMonth && d === tDay) || (wantFeb29Too && m === 2 && d === 29)
    })

    const results: Record<string, unknown>[] = []
    for (const person of birthdayPeople) {
      const { data: already } = await supabase
        .from('birthday_reminder_log')
        .select('employee_id')
        .eq('employee_id', person.id)
        .eq('year', tYear)
        .maybeSingle()
      if (already) { results.push({ name: person.name, skipped: 'already sent this year' }); continue }

      const bcc = withEmail.filter(e => e.id !== person.id).map(e => e.email)
      const mail = buildEmail(person.name, target)
      const sent = await sendMail(RESEND_API_KEY, { from: FROM_ADDRESS, to: [person.email], bcc, ...mail })

      if (sent.ok) {
        await supabase.from('birthday_reminder_log').insert({ employee_id: person.id, year: tYear })
        results.push({ name: person.name, sent: true, recipients: bcc.length + 1 })
      } else {
        console.error('[birthday-reminders] Resend error for', person.name, sent.data)
        results.push({ name: person.name, sent: false, error: sent.data })
      }
    }

    return new Response(JSON.stringify({ target: target.toISOString().slice(0, 10), matched: birthdayPeople.length, results }), { headers: JSON_HEADERS })
  } catch (err) {
    console.error('[birthday-reminders] fatal:', err)
    return new Response(JSON.stringify({ error: String(err) }), { status: 500, headers: JSON_HEADERS })
  }
})

// Hero banner (includes the Growthic One logo), served at HERO_URL (JPEG, base64).
const HERO_B64 =
  ''
